static double *GBUF_6, *GC_6;
static void ginit_6(void){
  GBUF_6 = (double*)xalloc((size_t)6*584*8 + 256);
  GC_6   = (double*)xalloc((size_t)6*584*8 + 256);
}
static void giter_6(double* restrict buf, const double* restrict cb){
  for(int y=0;y<6;y++) for(int z=0;z<6;z++) gA_6(buf + (size_t)y*96 + z*16);
  for(int x=0;x<6;x++){
    double* pb = buf + (size_t)x*584;
    for(int z=0;z<6;z++) gB_6(pb + z*16);
    for(int y=0;y<6;y++) gC_6(pb + (size_t)y*96, cb + (size_t)x*584 + (size_t)y*96);
  }
}
static void rungrp_6(const double* x0, const double* c, double* o1, double* om, long m){
  gconv_in_6(x0, GBUF_6);
  gconv_in_6(c, GC_6);
  for(long t=1;t<=m;t++){
    giter_6(GBUF_6, GC_6);
    if(t==1){
      gconv_out_6(GBUF_6, o1);
      if(m==1){ memcpy(om, o1, (size_t)216*8*16); return; }
    }
  }
  gconv_out_6(GBUF_6, om);
}

static void s39_run_6(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long g8 = B/8;
  for(long g=0; g<g8; g++)
    rungrp_6(x0 + (size_t)g*3456, c + (size_t)g*3456, o1 + (size_t)g*3456, om + (size_t)g*3456, m);
  for(long b=g8*8; b<B; b++)
    runvol_6(x0 + (size_t)b*432, c + (size_t)b*432, o1 + (size_t)b*432, om + (size_t)b*432, m);
}

