static void conv_in_8(const double* restrict src, double* restrict dst){
  for(int x=0;x<8;x++) for(int y=0;y<8;y++){
      const double* s = src + 2*((size_t)(x*8+y)*8);
      double* d = dst + (size_t)x*216 + (size_t)y*24;
      { __m512d a=_mm512_loadu_pd(s+0), b=_mm512_loadu_pd(s+8);
      ST(d+0, VD(_mm512_permutex2var_pd(a,IX(6),b))); ST(d+8, VD(_mm512_permutex2var_pd(a,IX(7),b))); }
  }
}
static void conv_c_8(const double* restrict src, double* restrict c0, double* restrict c1){
  vd trr[1][8], tri[1][8];
  for(int x=0;x<8;x++) for(int yb=0; yb<1; yb++){
    int ycnt = 8 - yb*8; if(ycnt>8) ycnt=8;
    for(int t=0;t<8;t++){
      int y = yb*8 + t;
      if(t < ycnt){
        const double* s = src + 2*((size_t)(x*8+y)*8);
        double* d = c0 + (size_t)x*216 + (size_t)y*24;
        { __m512d a=_mm512_loadu_pd(s+0), b=_mm512_loadu_pd(s+8);
      ST(d+0, VD(_mm512_permutex2var_pd(a,IX(6),b))); ST(d+8, VD(_mm512_permutex2var_pd(a,IX(7),b))); }
        for(int zb=0; zb<1; zb++){ trr[zb][t] = LD(d+zb*16); tri[zb][t] = LD(d+zb*16+8); }
      } else {
        for(int zb=0; zb<1; zb++){ trr[zb][t] = K(0.0); tri[zb][t] = K(0.0); }
      }
    }
    for(int zb=0; zb<1; zb++){
      int zcnt = 8 - zb*8; if(zcnt>8) zcnt=8;
      tr8a(trr[zb]); tr8a(tri[zb]);
      for(int u=0; u<zcnt; u++){
        int r = zb*8+u;
        ST(c1 + (size_t)x*216 + (size_t)r*24 + yb*16,     trr[zb][u]);
        ST(c1 + (size_t)x*216 + (size_t)r*24 + yb*16 + 8, tri[zb][u]);
      }
    }
  }
}
static void conv_out0_8(const double* restrict buf, double* restrict dst){
  for(int x=0;x<8;x++) for(int y=0;y<8;y++){
      const double* d = buf + (size_t)x*216 + (size_t)y*24;
      double* o = dst + 2*((size_t)(x*8+y)*8);
      { __m512d re=MD(LD(d+0)), im=MD(LD(d+8));
      __m512d a=_mm512_permutex2var_pd(re,IX(8),im), b=_mm512_permutex2var_pd(re,IX(9),im); _mm512_storeu_pd(o+0, a); _mm512_storeu_pd(o+8, b); }
  }
}
static void conv_out1_8(const double* restrict buf, double* restrict dst){
  vd trr[8], tri[8];
  for(int x=0;x<8;x++) for(int yb=0; yb<1; yb++){
    int ycnt = 8 - yb*8; if(ycnt>8) ycnt=8;
    for(int zb=0; zb<1; zb++){
      int zcnt = 8 - zb*8; if(zcnt>8) zcnt=8;
      for(int u=0;u<8;u++){
        int r = zb*8+u;
        if(u < zcnt){ trr[u] = LD(buf + (size_t)x*216 + (size_t)r*24 + yb*16); tri[u] = LD(buf + (size_t)x*216 + (size_t)r*24 + yb*16 + 8); }
        else { trr[u]=K(0.0); tri[u]=K(0.0); }
      }
      tr8a(trr); tr8a(tri);
      for(int t=0;t<ycnt;t++){
        int y = yb*8+t;
        double* o = dst + 2*((size_t)(x*8+y)*8 + (size_t)zb*8);
        __m512d a=_mm512_permutex2var_pd(MD(trr[t]),IX(8),MD(tri[t])), b=_mm512_permutex2var_pd(MD(trr[t]),IX(9),MD(tri[t]));
        if(zcnt==8){ _mm512_storeu_pd(o, a); _mm512_storeu_pd(o+8, b); }
        else { _mm512_mask_storeu_pd(o, 255, a); _mm512_mask_storeu_pd(o+8, 255, b); }
      }
    }
  }
}


static double *BUF_8, *C0_8, *C1_8, *SS_8;
static void init_8(void){
  BUF_8 = (double*)xalloc((size_t)8*216*8 + 256);
  C0_8  = (double*)xalloc((size_t)8*216*8 + 256);
  C1_8  = (double*)xalloc((size_t)8*216*8 + 256);
  SS_8  = (double*)xalloc((size_t)8*24*8 + 256);
}
static void iter_8(double* restrict buf, const double* restrict cb){
  for(int y=0;y<8;y++){
    double* q = buf + (size_t)y*24;
    for(int zb=0; zb<1; zb++) fA_8(q + zb*16);
  }
  for(int x=0;x<8;x++){
    double* pl = buf + (size_t)x*216;
    fBC_8(pl, cb + (size_t)x*216);
  }
}
static void runvol_8(const double* x0, const double* c, double* o1, double* om, long m){
  conv_in_8(x0, BUF_8);
  conv_c_8(c, C0_8, C1_8);
  for(long t=1;t<=m;t++){
    iter_8(BUF_8, (t&1)? C1_8 : C0_8);
    if(t==1){
      conv_out1_8(BUF_8, o1);
      if(m==1){ memcpy(om, o1, (size_t)512*16); return; }
    }
  }
  if(m&1) conv_out1_8(BUF_8, om); else conv_out0_8(BUF_8, om);
}

