static double *GBUF_8, *GC_8;
static void ginit_8(void){
  GBUF_8 = (double*)xalloc((size_t)8*1032*8 + 256);
  GC_8   = (double*)xalloc((size_t)8*1032*8 + 256);
}
static void giter_8(double* restrict buf, const double* restrict cb){
  for(int y=0;y<8;y++) for(int z=0;z<8;z++) gA_8(buf + (size_t)y*128 + z*16);
  for(int x=0;x<8;x++){
    double* pb = buf + (size_t)x*1032;
    for(int z=0;z<8;z++) gB_8(pb + z*16);
    for(int y=0;y<8;y++) gC_8(pb + (size_t)y*128, cb + (size_t)x*1032 + (size_t)y*128);
  }
}
static void rungrp_8(const double* x0, const double* c, double* o1, double* om, long m){
  gconv_in_8(x0, GBUF_8);
  gconv_in_8(c, GC_8);
  for(long t=1;t<=m;t++){
    giter_8(GBUF_8, GC_8);
    if(t==1){
      gconv_out_8(GBUF_8, o1);
      if(m==1){ memcpy(om, o1, (size_t)512*8*16); return; }
    }
  }
  gconv_out_8(GBUF_8, om);
}

static void s39_run_8(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long g8 = B/8;
  for(long g=0; g<g8; g++)
    rungrp_8(x0 + (size_t)g*8192, c + (size_t)g*8192, o1 + (size_t)g*8192, om + (size_t)g*8192, m);
  for(long b=g8*8; b<B; b++)
    runvol_8(x0 + (size_t)b*1024, c + (size_t)b*1024, o1 + (size_t)b*1024, om + (size_t)b*1024, m);
}

