static void giter_13(double* restrict buf, const double* restrict cb){
  for(int y=0;y<13;y++) for(int z=0;z<13;z++) gA_13(buf + (size_t)y*208 + z*16);
  for(int x=0;x<13;x++){
    double* pb = buf + (size_t)x*2712;
    for(int z=0;z<13;z++) gB_13(pb + z*16);
    for(int y=0;y<13;y++) gC_13(pb + (size_t)y*208, cb + (size_t)x*2712 + (size_t)y*208);
  }
}
static void rungrp_13(const double* x0, const double* c, double* o1, double* om, long m){
  gconv_in_13(x0, GBUF_13);
  gconv_in_13(c, GC_13);
  for(long t=1;t<=m;t++){
    giter_13(GBUF_13, GC_13);
    if(t==1){
      gconv_out_13(GBUF_13, o1);
      if(m==1){ memcpy(om, o1, (size_t)2197*8*16); return; }
    }
  }
  gconv_out_13(GBUF_13, om);
}

static void s39_run_13(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long g8 = B/8;
  for(long g=0; g<g8; g++)
    rungrp_13(x0 + (size_t)g*35152, c + (size_t)g*35152, o1 + (size_t)g*35152, om + (size_t)g*35152, m);
  for(long b=g8*8; b<B; b++)
    runvol_13(x0 + (size_t)b*4394, c + (size_t)b*4394, o1 + (size_t)b*4394, om + (size_t)b*4394, m);
}

