static double *GBUF_17, *GC_17;
static void ginit_17(void){
  GBUF_17 = (double*)xalloc((size_t)17*4632*8 + 256);
  GC_17   = (double*)xalloc((size_t)17*4632*8 + 256);
}
static void giter_17(double* restrict buf, const double* restrict cb){
  for(int y=0;y<17;y++) for(int z=0;z<17;z++) gA_17(buf + (size_t)y*272 + z*16);
  for(int x=0;x<17;x++){
    double* pb = buf + (size_t)x*4632;
    for(int z=0;z<17;z++) gB_17(pb + z*16);
    for(int y=0;y<17;y++) gC_17(pb + (size_t)y*272, cb + (size_t)x*4632 + (size_t)y*272);
  }
}
static void rungrp_17(const double* x0, const double* c, double* o1, double* om, long m){
  gconv_in_17(x0, GBUF_17);
  gconv_in_17(c, GC_17);
  for(long t=1;t<=m;t++){
    giter_17(GBUF_17, GC_17);
    if(t==1){
      gconv_out_17(GBUF_17, o1);
      if(m==1){ memcpy(om, o1, (size_t)4913*8*16); return; }
    }
  }
  gconv_out_17(GBUF_17, om);
}

static void s39_run_17(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long g8 = B/8;
  for(long g=0; g<g8; g++)
    rungrp_17(x0 + (size_t)g*78608, c + (size_t)g*78608, o1 + (size_t)g*78608, om + (size_t)g*78608, m);
  for(long b=g8*8; b<B; b++)
    runvol_17(x0 + (size_t)b*9826, c + (size_t)b*9826, o1 + (size_t)b*9826, om + (size_t)b*9826, m);
}

