static double *GBUF_23, *GC_23;
static void ginit_23(void){
  GBUF_23 = (double*)xalloc((size_t)23*8472*8 + 256);
  GC_23   = (double*)xalloc((size_t)23*8472*8 + 256);
}
static void giter_23(double* restrict buf, const double* restrict cb){
  for(int y=0;y<23;y++) for(int z=0;z<23;z++) gA_23(buf + (size_t)y*368 + z*16);
  for(int x=0;x<23;x++){
    double* pb = buf + (size_t)x*8472;
    for(int z=0;z<23;z++) gB_23(pb + z*16);
    for(int y=0;y<23;y++) gC_23(pb + (size_t)y*368, cb + (size_t)x*8472 + (size_t)y*368);
  }
}
static void rungrp_23(const double* x0, const double* c, double* o1, double* om, long m){
  gconv_in_23(x0, GBUF_23);
  gconv_in_23(c, GC_23);
  for(long t=1;t<=m;t++){
    giter_23(GBUF_23, GC_23);
    if(t==1){
      gconv_out_23(GBUF_23, o1);
      if(m==1){ memcpy(om, o1, (size_t)12167*8*16); return; }
    }
  }
  gconv_out_23(GBUF_23, om);
}

static void s39_run_23(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long g8 = B/8;
  for(long g=0; g<g8; g++)
    rungrp_23(x0 + (size_t)g*194672, c + (size_t)g*194672, o1 + (size_t)g*194672, om + (size_t)g*194672, m);
  for(long b=g8*8; b<B; b++)
    runvol_23(x0 + (size_t)b*24334, c + (size_t)b*24334, o1 + (size_t)b*24334, om + (size_t)b*24334, m);
}

