static double *BUF_36, *C0_36, *C1_36, *SS_36;
static void init_36(void){
  BUF_36 = (double*)xalloc((size_t)36*3544*8 + 256);
  C0_36  = (double*)xalloc((size_t)36*3544*8 + 256);
  C1_36  = (double*)xalloc((size_t)36*3544*8 + 256);
  SS_36  = (double*)xalloc((size_t)40*88*8 + 256);
}
static void iter_36(double* restrict buf, const double* restrict cb){
  for(int y=0;y<36;y++){
    double* q = buf + (size_t)y*88;
    for(int zb=0; zb<5; zb++) fA_36(q + zb*16);
  }
  for(int x=0;x<36;x++){
    double* pl = buf + (size_t)x*3544;
    for(int zb=0; zb<5; zb++) fB_36(pl + zb*16, SS_36 + zb*16);
    fC_36(pl, SS_36, cb + (size_t)x*3544);
  }
}
static void runvol_36(const double* x0, const double* c, double* o1, double* om, long m){
  conv_in_36(x0, BUF_36);
  conv_c_36(c, C0_36, C1_36);
  for(long t=1;t<=m;t++){
    iter_36(BUF_36, (t&1)? C1_36 : C0_36);
    if(t==1){
      conv_out1_36(BUF_36, o1);
      if(m==1){ memcpy(om, o1, (size_t)46656*16); return; }
    }
  }
  if(m&1) conv_out1_36(BUF_36, om); else conv_out0_36(BUF_36, om);
}

