static double *GBUF_36, *GC_36;
static void ginit_36(void){
  GBUF_36 = (double*)xalloc((size_t)36*20744*8 + 256);
  GC_36   = (double*)xalloc((size_t)36*20744*8 + 256);
}
static void giter_36(double* restrict buf, const double* restrict cb){
  for(int y=0;y<36;y++) for(int z=0;z<36;z++) gA_36(buf + (size_t)y*576 + z*16);
  for(int x=0;x<36;x++){
    double* pb = buf + (size_t)x*20744;
    for(int z=0;z<36;z++) gB_36(pb + z*16);
    for(int y=0;y<36;y++) gC_36(pb + (size_t)y*576, cb + (size_t)x*20744 + (size_t)y*576);
  }
}
static void rungrp_36(const double* x0, const double* c, double* o1, double* om, long m){
  gconv_in_36(x0, GBUF_36);
  gconv_in_36(c, GC_36);
  for(long t=1;t<=m;t++){
    giter_36(GBUF_36, GC_36);
    if(t==1){
      gconv_out_36(GBUF_36, o1);
      if(m==1){ memcpy(om, o1, (size_t)46656*8*16); return; }
    }
  }
  gconv_out_36(GBUF_36, om);
}

static void s39_run_36(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long g8 = B/8;
  for(long g=0; g<g8; g++)
    rungrp_36(x0 + (size_t)g*746496, c + (size_t)g*746496, o1 + (size_t)g*746496, om + (size_t)g*746496, m);
  for(long b=g8*8; b<B; b++)
    runvol_36(x0 + (size_t)b*93312, c + (size_t)b*93312, o1 + (size_t)b*93312, om + (size_t)b*93312, m);
}

