static double *BUF_45, *C0_45, *C1_45, *SS_45;
static void init_45(void){
  BUF_45 = (double*)xalloc((size_t)45*5016*8 + 256);
  C0_45  = (double*)xalloc((size_t)45*5016*8 + 256);
  C1_45  = (double*)xalloc((size_t)45*5016*8 + 256);
  SS_45  = (double*)xalloc((size_t)48*104*8 + 256);
}
static void iter_45(double* restrict buf, const double* restrict cb){
  for(int y=0;y<45;y++){
    double* q = buf + (size_t)y*104;
    for(int zb=0; zb<6; zb++) fA_45(q + zb*16);
  }
  for(int x=0;x<45;x++){
    double* pl = buf + (size_t)x*5016;
    for(int zb=0; zb<6; zb++) fB_45(pl + zb*16, SS_45 + zb*16);
    fC_45(pl, SS_45, cb + (size_t)x*5016);
  }
}
static void runvol_45(const double* x0, const double* c, double* o1, double* om, long m){
  conv_in_45(x0, BUF_45);
  conv_c_45(c, C0_45, C1_45);
  for(long t=1;t<=m;t++){
    iter_45(BUF_45, (t&1)? C1_45 : C0_45);
    if(t==1){
      conv_out1_45(BUF_45, o1);
      if(m==1){ memcpy(om, o1, (size_t)91125*16); return; }
    }
  }
  if(m&1) conv_out1_45(BUF_45, om); else conv_out0_45(BUF_45, om);
}

