static double *GBUF_45, *GC_45;
static void ginit_45(void){
  GBUF_45 = (double*)xalloc((size_t)45*32408*8 + 256);
  GC_45   = (double*)xalloc((size_t)45*32408*8 + 256);
}
static void giter_45(double* restrict buf, const double* restrict cb){
  for(int y=0;y<45;y++) for(int z=0;z<45;z++) gA_45(buf + (size_t)y*720 + z*16);
  for(int x=0;x<45;x++){
    double* pb = buf + (size_t)x*32408;
    for(int z=0;z<45;z++) gB_45(pb + z*16);
    for(int y=0;y<45;y++) gC_45(pb + (size_t)y*720, cb + (size_t)x*32408 + (size_t)y*720);
  }
}
static void rungrp_45(const double* x0, const double* c, double* o1, double* om, long m){
  gconv_in_45(x0, GBUF_45);
  gconv_in_45(c, GC_45);
  for(long t=1;t<=m;t++){
    giter_45(GBUF_45, GC_45);
    if(t==1){
      gconv_out_45(GBUF_45, o1);
      if(m==1){ memcpy(om, o1, (size_t)91125*8*16); return; }
    }
  }
  gconv_out_45(GBUF_45, om);
}

static void s39_run_45(long B, long m, const double* x0, const double* c, double* o1, double* om){
  long g8 = B/8;
  for(long g=0; g<g8; g++)
    rungrp_45(x0 + (size_t)g*1458000, c + (size_t)g*1458000, o1 + (size_t)g*1458000, om + (size_t)g*1458000, m);
  for(long b=g8*8; b<B; b++)
    runvol_45(x0 + (size_t)b*182250, c + (size_t)b*182250, o1 + (size_t)b*182250, om + (size_t)b*182250, m);
}

