static void s39_conv_in_64(const double* restrict src, double* restrict dst){
  for(int x=0;x<64;x++) for(int y=0;y<64;y++){
      const double* s = src + 2*((size_t)(x*64+y)*64);
      double* d = dst + (size_t)x*8728 + (size_t)y*136;
      __m512d p0 = _mm512_loadu_pd(s+0), q0 = _mm512_loadu_pd(s+8);
      vd a0 = VD(_mm512_permutex2var_pd(p0,IX(6),q0));
      vd b0 = VD(_mm512_permutex2var_pd(p0,IX(7),q0));
      __m512d p1 = _mm512_loadu_pd(s+16), q1 = _mm512_loadu_pd(s+24);
      vd a1 = VD(_mm512_permutex2var_pd(p1,IX(6),q1));
      vd b1 = VD(_mm512_permutex2var_pd(p1,IX(7),q1));
      __m512d p2 = _mm512_loadu_pd(s+32), q2 = _mm512_loadu_pd(s+40);
      vd a2 = VD(_mm512_permutex2var_pd(p2,IX(6),q2));
      vd b2 = VD(_mm512_permutex2var_pd(p2,IX(7),q2));
      __m512d p3 = _mm512_loadu_pd(s+48), q3 = _mm512_loadu_pd(s+56);
      vd a3 = VD(_mm512_permutex2var_pd(p3,IX(6),q3));
      vd b3 = VD(_mm512_permutex2var_pd(p3,IX(7),q3));
      __m512d p4 = _mm512_loadu_pd(s+64), q4 = _mm512_loadu_pd(s+72);
      vd a4 = VD(_mm512_permutex2var_pd(p4,IX(6),q4));
      vd b4 = VD(_mm512_permutex2var_pd(p4,IX(7),q4));
      __m512d p5 = _mm512_loadu_pd(s+80), q5 = _mm512_loadu_pd(s+88);
      vd a5 = VD(_mm512_permutex2var_pd(p5,IX(6),q5));
      vd b5 = VD(_mm512_permutex2var_pd(p5,IX(7),q5));
      __m512d p6 = _mm512_loadu_pd(s+96), q6 = _mm512_loadu_pd(s+104);
      vd a6 = VD(_mm512_permutex2var_pd(p6,IX(6),q6));
      vd b6 = VD(_mm512_permutex2var_pd(p6,IX(7),q6));
      __m512d p7 = _mm512_loadu_pd(s+112), q7 = _mm512_loadu_pd(s+120);
      vd a7 = VD(_mm512_permutex2var_pd(p7,IX(6),q7));
      vd b7 = VD(_mm512_permutex2var_pd(p7,IX(7),q7));
      s39_TR8(a0,a1,a2,a3,a4,a5,a6,a7);
      s39_TR8(b0,b1,b2,b3,b4,b5,b6,b7);
      ST(d+0, a0); ST(d+8, b0);
      ST(d+16, a1); ST(d+24, b1);
      ST(d+32, a2); ST(d+40, b2);
      ST(d+48, a3); ST(d+56, b3);
      ST(d+64, a4); ST(d+72, b4);
      ST(d+80, a5); ST(d+88, b5);
      ST(d+96, a6); ST(d+104, b6);
      ST(d+112, a7); ST(d+120, b7);
  }
}
static void conv_c_64(const double* restrict src, double* restrict c0, double* restrict c1){
  for(int x=0;x<64;x++){
    vd t0r[8][8], t0i[8][8]; /* [zb][u] pre-swap */
    for(int kb=0; kb<8; kb++){
      for(int u=0; u<8; u++){
        int y = u*8+kb;
        const double* s = src + 2*((size_t)(x*64+y)*64);
        double* d = c0 + (size_t)x*8728 + (size_t)y*16;
        __m512d p0 = _mm512_loadu_pd(s+0), q0 = _mm512_loadu_pd(s+8);
    vd a0 = VD(_mm512_permutex2var_pd(p0,IX(6),q0));
    vd b0 = VD(_mm512_permutex2var_pd(p0,IX(7),q0));
    t0r[0][u] = a0; t0i[0][u] = b0;
    __m512d p1 = _mm512_loadu_pd(s+16), q1 = _mm512_loadu_pd(s+24);
    vd a1 = VD(_mm512_permutex2var_pd(p1,IX(6),q1));
    vd b1 = VD(_mm512_permutex2var_pd(p1,IX(7),q1));
    t0r[1][u] = a1; t0i[1][u] = b1;
    __m512d p2 = _mm512_loadu_pd(s+32), q2 = _mm512_loadu_pd(s+40);
    vd a2 = VD(_mm512_permutex2var_pd(p2,IX(6),q2));
    vd b2 = VD(_mm512_permutex2var_pd(p2,IX(7),q2));
    t0r[2][u] = a2; t0i[2][u] = b2;
    __m512d p3 = _mm512_loadu_pd(s+48), q3 = _mm512_loadu_pd(s+56);
    vd a3 = VD(_mm512_permutex2var_pd(p3,IX(6),q3));
    vd b3 = VD(_mm512_permutex2var_pd(p3,IX(7),q3));
    t0r[3][u] = a3; t0i[3][u] = b3;
    __m512d p4 = _mm512_loadu_pd(s+64), q4 = _mm512_loadu_pd(s+72);
    vd a4 = VD(_mm512_permutex2var_pd(p4,IX(6),q4));
    vd b4 = VD(_mm512_permutex2var_pd(p4,IX(7),q4));
    t0r[4][u] = a4; t0i[4][u] = b4;
    __m512d p5 = _mm512_loadu_pd(s+80), q5 = _mm512_loadu_pd(s+88);
    vd a5 = VD(_mm512_permutex2var_pd(p5,IX(6),q5));
    vd b5 = VD(_mm512_permutex2var_pd(p5,IX(7),q5));
    t0r[5][u] = a5; t0i[5][u] = b5;
    __m512d p6 = _mm512_loadu_pd(s+96), q6 = _mm512_loadu_pd(s+104);
    vd a6 = VD(_mm512_permutex2var_pd(p6,IX(6),q6));
    vd b6 = VD(_mm512_permutex2var_pd(p6,IX(7),q6));
    t0r[6][u] = a6; t0i[6][u] = b6;
    __m512d p7 = _mm512_loadu_pd(s+112), q7 = _mm512_loadu_pd(s+120);
    vd a7 = VD(_mm512_permutex2var_pd(p7,IX(6),q7));
    vd b7 = VD(_mm512_permutex2var_pd(p7,IX(7),q7));
    t0r[7][u] = a7; t0i[7][u] = b7;
    s39_TR8(a0,a1,a2,a3,a4,a5,a6,a7);
    s39_TR8(b0,b1,b2,b3,b4,b5,b6,b7);
    ST(d+0, a0); ST(d+8, b0);
    ST(d+1024, a1); ST(d+1032, b1);
    ST(d+2048, a2); ST(d+2056, b2);
    ST(d+3072, a3); ST(d+3080, b3);
    ST(d+4096, a4); ST(d+4104, b4);
    ST(d+5120, a5); ST(d+5128, b5);
    ST(d+6144, a6); ST(d+6152, b6);
    ST(d+7168, a7); ST(d+7176, b7);
      }
      for(int zb=0; zb<8; zb++){
        tr8a(t0r[zb]); tr8a(t0i[zb]);
        for(int u=0; u<8; u++){ int r = zb*8+u;
          ST(c1 + (size_t)x*8728 + (size_t)(kb*64 + r)*16, t0r[zb][u]);
          ST(c1 + (size_t)x*8728 + (size_t)(kb*64 + r)*16 + 8, t0i[zb][u]); }
      }
    }
  }
}
static void conv_out0_64(const double* restrict buf, double* restrict dst){
  for(int x=0;x<64;x++) for(int y=0;y<64;y++){
      const double* d = buf + (size_t)x*8728 + (size_t)y*136;
      double* o = dst + 2*((size_t)(x*64+y)*64);
      vd a0 = LD(d+0); vd b0 = LD(d+8);
      vd a1 = LD(d+16); vd b1 = LD(d+24);
      vd a2 = LD(d+32); vd b2 = LD(d+40);
      vd a3 = LD(d+48); vd b3 = LD(d+56);
      vd a4 = LD(d+64); vd b4 = LD(d+72);
      vd a5 = LD(d+80); vd b5 = LD(d+88);
      vd a6 = LD(d+96); vd b6 = LD(d+104);
      vd a7 = LD(d+112); vd b7 = LD(d+120);
      s39_TR8(a0,a1,a2,a3,a4,a5,a6,a7);
      s39_TR8(b0,b1,b2,b3,b4,b5,b6,b7);
      _mm512_storeu_pd(o+0, _mm512_permutex2var_pd(MD(a0),IX(8),MD(b0)));
      _mm512_storeu_pd(o+8, _mm512_permutex2var_pd(MD(a0),IX(9),MD(b0)));
      _mm512_storeu_pd(o+16, _mm512_permutex2var_pd(MD(a1),IX(8),MD(b1)));
      _mm512_storeu_pd(o+24, _mm512_permutex2var_pd(MD(a1),IX(9),MD(b1)));
      _mm512_storeu_pd(o+32, _mm512_permutex2var_pd(MD(a2),IX(8),MD(b2)));
      _mm512_storeu_pd(o+40, _mm512_permutex2var_pd(MD(a2),IX(9),MD(b2)));
      _mm512_storeu_pd(o+48, _mm512_permutex2var_pd(MD(a3),IX(8),MD(b3)));
      _mm512_storeu_pd(o+56, _mm512_permutex2var_pd(MD(a3),IX(9),MD(b3)));
      _mm512_storeu_pd(o+64, _mm512_permutex2var_pd(MD(a4),IX(8),MD(b4)));
      _mm512_storeu_pd(o+72, _mm512_permutex2var_pd(MD(a4),IX(9),MD(b4)));
      _mm512_storeu_pd(o+80, _mm512_permutex2var_pd(MD(a5),IX(8),MD(b5)));
      _mm512_storeu_pd(o+88, _mm512_permutex2var_pd(MD(a5),IX(9),MD(b5)));
      _mm512_storeu_pd(o+96, _mm512_permutex2var_pd(MD(a6),IX(8),MD(b6)));
      _mm512_storeu_pd(o+104, _mm512_permutex2var_pd(MD(a6),IX(9),MD(b6)));
      _mm512_storeu_pd(o+112, _mm512_permutex2var_pd(MD(a7),IX(8),MD(b7)));
      _mm512_storeu_pd(o+120, _mm512_permutex2var_pd(MD(a7),IX(9),MD(b7)));
  }
}
static void conv_out1_64(const double* restrict buf, double* restrict dst){
  for(int x=0;x<64;x++){
    vd trr[8], tri[8];
    for(int kb=0; kb<8; kb++) for(int zb=0; zb<8; zb++){
      for(int u=0;u<8;u++){ int r = zb*8+u; trr[u] = LD(buf + (size_t)x*8728 + (size_t)r*136 + kb*16); tri[u] = LD(buf + (size_t)x*8728 + (size_t)r*136 + kb*16 + 8); }
      tr8a(trr); tr8a(tri);
      /* vector_u over z-lanes s for y = u*8+kb */
      for(int u=0;u<8;u++){ int y = u*8+kb;
        double* o = dst + 2*((size_t)(x*64+y)*64 + (size_t)zb*8);
        _mm512_storeu_pd(o,   _mm512_permutex2var_pd(MD(trr[u]),IX(8),MD(tri[u])));
        _mm512_storeu_pd(o+8, _mm512_permutex2var_pd(MD(trr[u]),IX(9),MD(tri[u])));
      }
    }
  }
}


static double *BUF_64, *C0_64, *C1_64, *SS_64;
static void init_64(void){
  BUF_64 = (double*)xalloc((size_t)64*8728*8 + 256);
  C0_64  = (double*)xalloc((size_t)64*8728*8 + 256);
  C1_64  = (double*)xalloc((size_t)64*8728*8 + 256);
  SS_64  = (double*)xalloc((size_t)64*136*8 + 256);
}
static void iter_64(double* restrict buf, const double* restrict cb){
  for(int y=0;y<64;y++){
    double* q = buf + (size_t)y*136;
    for(int zb=0; zb<8; zb++) fA_64(q + zb*16);
  }
  for(int x=0;x<64;x++){
    double* pl = buf + (size_t)x*8728;
    for(int zb=0; zb<8; zb++) fB_64(pl + zb*16, SS_64 + (size_t)zb*136);
    fC_64(pl, SS_64, cb + (size_t)x*8728);
  }
}
static void runvol_64(const double* x0, const double* c, double* o1, double* om, long m){
  s39_conv_in_64(x0, BUF_64);
  conv_c_64(c, C0_64, C1_64);
  for(long t=1;t<=m;t++){
    iter_64(BUF_64, (t&1)? C1_64 : C0_64);
    if(t==1){
      conv_out1_64(BUF_64, o1);
      if(m==1){ memcpy(om, o1, (size_t)262144*16); return; }
    }
  }
  if(m&1) conv_out1_64(BUF_64, om); else conv_out0_64(BUF_64, om);
}

static void s39_run_64(long B, long m, const double* x0, const double* c, double* o1, double* om){
  for(long b=0;b<B;b++)
    runvol_64(x0 + (size_t)b*524288, c + (size_t)b*524288, o1 + (size_t)b*524288, om + (size_t)b*524288, m);
}
static void s39_init_all(void){ init_6(); init_8(); init_13(); init_17(); init_23(); init_36(); init_45(); init_64(); ginit_6(); ginit_8(); ginit_13(); ginit_17(); ginit_23(); ginit_36(); ginit_45(); }
static void s39_run(int lid, long B, long m, const double* x0, const double* c, double* o1, double* om){
  switch(lid){
    case 0: s39_run_6(B,m,x0,c,o1,om); break;
    case 1: s39_run_8(B,m,x0,c,o1,om); break;
    case 2: s39_run_13(B,m,x0,c,o1,om); break;
    case 3: s39_run_17(B,m,x0,c,o1,om); break;
    case 4: s39_run_23(B,m,x0,c,o1,om); break;
    case 5: s39_run_36(B,m,x0,c,o1,om); break;
    case 6: s39_run_45(B,m,x0,c,o1,om); break;
    case 7: s39_run_64(B,m,x0,c,o1,om); break;
  }
}
#pragma GCC pop_options

void run_45(const double* x0, const double* c, double* out1, double* outm, long B, long m){
    if (B < 8) { w00_run_45(x0, c, out1, outm, B, m); return; }
    static int s39_inited = 0;
    if (!s39_inited) { s39_init_all(); s39_inited = 1; }
    s39_run_45(B, m, x0, c, out1, outm);
}

